package pe.greenminds.ecomind.monetization.infrastructure.persistence.jpa.repositories;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import pe.greenminds.ecomind.monetization.infrastructure.persistence.jpa.entities.ProtectorInventoryPersistenceEntity;
public interface ProtectorInventoryPersistenceRepository extends JpaRepository<ProtectorInventoryPersistenceEntity,String>{ List<ProtectorInventoryPersistenceEntity> findByUserId(Long u); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select p from ProtectorInventoryPersistenceEntity p where p.userId=:u and p.quantity>0 order by p.id") List<ProtectorInventoryPersistenceEntity> lockAvailable(@Param("u") Long u); Optional<ProtectorInventoryPersistenceEntity> findByUserIdAndProtectorId(Long u,String p); }
